<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesFilter;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesReadGateway;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesWriteGateway;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\UserConsentedScopesAttributes;
use Civi\Lughauth\Features\OAuth\Profile\Domain\ConsentedClient;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\ConsentedScopesGateway;

final class ConsentedScopesAdapter implements ConsentedScopesGateway
{
    public function __construct(
        private readonly UserConsentedScopesReadGateway $consentsRead,
        private readonly UserConsentedScopesWriteGateway $consentsWrite,
        private readonly TrustedClientReadGateway $trustedClients,
    ) {
    }

    #[Override]
    public function listByUser(string $userUid): array
    {
        $filter = (new UserConsentedScopesFilter())->withUser(new UserRef($userUid));
        $slide = $this->consentsRead->list($filter);
        $result = [];
        foreach ($slide->values() as $consent) {
            $clientUid = $consent->getTrustedClient()->uid() ?? '';
            $client = $this->trustedClients->findOneByUid($clientUid);
            $clientId = $client?->getCode() ?? $clientUid;
            $clientName = $client?->getClientName() ?? $clientId;
            $result[] = new ConsentedClient(
                consentUid: $consent->uid() ?? '',
                clientUid: $clientUid,
                clientId: $clientId,
                clientName: $clientName,
                scopes: $consent->getScope() ?? '',
                grantedAt: $consent->getDecisionAt(),
            );
        }
        return $result;
    }

    #[Override]
    public function revokeByUid(string $consentUid): void
    {
        $consent = $this->consentsWrite->findOneForUpdateByUid($consentUid);
        if ($consent === null) {
            return;
        }
        $this->consentsWrite->delete($consent);
    }

    #[Override]
    public function revokeScopeByUid(string $consentUid, string $scope): void
    {
        $consent = $this->consentsWrite->findOneForUpdateByUid($consentUid);
        if ($consent === null) {
            return;
        }
        $existing = array_filter(
            explode(' ', $consent->getScope() ?? ''),
            fn($s) => trim($s) !== '' && trim($s) !== $scope
        );
        $newScope = implode(' ', array_values($existing));

        if ($newScope === '') {
            $this->consentsWrite->delete($consent);
            return;
        }

        $updated = $consent->update(
            (new UserConsentedScopesAttributes())->scope($newScope)
        );
        $this->consentsWrite->update($consent, $updated);
    }
}
